"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["67178"],{87567(e){e.exports=JSON.parse('{"id":"FIN-1112","slug":"agency-cost","term":"Agency Cost","also_known_as":[],"difficulty":"Advanced","definition":"Agency cost is the cost that arises from conflicts of interest between people who own a business, or have a stake in it, and the people who manage it on their behalf.","explanation":["In a company, shareholders are the principals and managers are their agents. Managers may sometimes act in their own interest rather than the shareholders\', for example by pursuing expensive acquisitions to build a larger empire, taking excessive perks or avoiding risky but valuable projects to protect their jobs.","Agency costs include the loss of value from such decisions, and the costs of trying to prevent them, such as audits, board oversight, monitoring and performance-related pay. They also include bonding costs, such as managers accepting contracts that tie their pay to performance.","Conflicts can also arise between shareholders and lenders. For example, shareholders of a struggling company may prefer very risky projects, since they gain if the gamble succeeds while lenders bear much of the loss if it fails.","Agency costs were formalised in a well-known 1976 paper by Michael Jensen and William Meckling. Ways to reduce them include linking executive pay to long-term performance, independent boards, active shareholders, loan covenants and, some argue, debt itself, which limits the free cash available to managers."],"note":"","total":1500,"prev":{"slug":"after-tax-return","term":"After-Tax Return"},"next":{"slug":"aggregate-demand","term":"Aggregate Demand"}}')}}]);